import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

public class AnnotationIntrospector_refineSerializationType_TriageGen0Test {

    private AnnotationIntrospector introspector;
    private MapperConfig<?> config;
    private TypeFactory typeFactory;
    private Annotated annotated;

    @Before
    public void setUp() {
        // We must use a spy because refineSerializationType calls findSerializationType, 
        // findSerializationKeyType, and findSerializationContentType which are abstract.
        introspector = spy(AnnotationIntrospector.nopInstance());
        config = Mockito.mock(MapperConfig.class);
        typeFactory = TypeFactory.defaultInstance();
        annotated = Mockito.mock(Annotated.class);

        when(config.getTypeFactory()).thenReturn(typeFactory);
    }

    @Test
    public void testRefineSerializationType_NoAnnotation() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(String.class);
        when(introspector.findSerializationType(annotated)).thenReturn(null);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(baseType, result);
    }

    @Test
    public void testRefineSerializationType_WithStaticTypingMatch() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(String.class);
        when(introspector.findSerializationType(annotated)).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertTrue(result.hasStaticTyping());
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testRefineSerializationType_WithWidenType() throws JsonMappingException {
        // Base type is Object, Annotation says String
        JavaType baseType = typeFactory.constructType(Object.class);
        when(introspector.findSerializationType(annotated)).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(String.class, result.getRawClass());
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineSerializationType_WidenTypeFailure() throws JsonMappingException {
        // Use a type that cannot be widened (e.g., trying to force a non-compatible type via TypeFactory)
        // Note: TypeFactory.constructGeneralizedType usually throws IllegalArgumentException if types are incompatible
        JavaType baseType = typeFactory.constructType(Integer.class);
        when(introspector.findSerializationType(annotated)).thenReturn(String.class);

        // We simulate a failure in the widening logic by providing a type that cannot be generalized
        // In real Jackson, this happens if the internal TypeFactory logic hits an illegal state
        // Here we force the behavior by using an incompatible structure if possible, or mocking the TF
        // However, since we use the real TF, we rely on the fact that if it fails, it throws.
        // Let's use a scenario where constructGeneralizedType might fail.
        // Forcing it via a mock of TypeFactory is more reliable for coverage.
        TypeFactory mockedTf = Mockito.mock(TypeFactory.class);
        when(config.getTypeFactory()).thenReturn(mockedTf);
        when(mockedTf.constructGeneralizedType(any(), any())).thenThrow(new IllegalArgumentException("Mock Fail"));

        introspector.refineSerializationType(config, annotated, baseType);
    }

    @Test
    public void testRefineSerializationType_MapKeyRefinement_Widen() throws JsonMappingException {
        // Map<Object, Object> -> Annotation says Map<String, Object>
        JavaType baseType = typeFactory.constructMapType(HashMap.class, Object.class, Object.class);
        when(introspector.findSerializationType(annotated)).thenReturn(null);
        when(introspector.findSerializationKeyType(any(Annotated.class), any(JavaType.class))).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(String.class, result.getKeyType().getRawClass());
        assertEquals(Object.class, result.getContentType().getRawClass());
    }

    @Test
    public void testRefineSerializationType_MapKeyRefinement_StaticTyping() throws JsonMappingException {
        // Map<String, Object> -> Annotation says Map<String, Object> (already matches)
        JavaType baseType = typeFactory.constructMapType(HashMap.class, String.class, Object.class);
        when(introspector.findSerializationKeyType(any(Annotated.class), any(JavaType.class))).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertTrue(result.getKeyType().hasStaticTyping());
    }

    @Test
    public void testRefineSerializationType_MapKeyRefinement_Specialization() throws JsonMappingException {
        // Map<String, Object> -> Annotation says Map<Object, Object> (specializing String to Object is actually widening, 
        // but the code handles currRaw.isAssignableFrom(keyClass) as specialization)
        // To trigger the 'else if (currRaw.isAssignableFrom(keyClass))' [Specialization]:
        // keyClass = String.class, currRaw = Object.class -> Object.isAssignableFrom(String) is true.
        // Wait, the code says: 
        // if (keyClass.isAssignableFrom(currRaw)) -> Widen (e.g. keyClass=Object, currRaw=String)
        // else if (currRaw.isAssignableFrom(keyClass)) -> Specialize (e.g. keyClass=String, currRaw=Object)

        JavaType baseType = typeFactory.constructMapType(HashMap.class, Object.class, Object.class);
        when(introspector.findSerializationKeyType(any(Annotated.class), any(JavaType.class))).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);
        assertEquals(String.class, result.getKeyType().getRawClass());
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineSerializationType_MapKeyRefinement_Incompatible() throws JsonMappingException {
        JavaType baseType = typeFactory.constructMapType(HashMap.class, Integer.class, Object.class);
        when(introspector.findSerializationKeyType(any(Annotated.class), any(JavaType.class))).thenReturn(String.class);

        introspector.refineSerializationType(config, annotated, baseType);
    }

    @Test
    public void testRefineSerializationType_ContentTypeRefinement_Widen() throws JsonMappingException {
        // List<Object> -> Annotation says List<String>
        JavaType baseType = typeFactory.constructArrayType(Object[].class, Object.class);
        when(introspector.findSerializationType(annotated)).thenReturn(null);
        when(introspector.findSerializationContentType(any(Annotated.class), any(JavaType.class))).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(String.class, result.getContentType().getRawClass());
    }

    @Test
    public void testRefineSerializationType_ContentTypeRefinement_StaticTyping() throws JsonMappingException {
        // List<String> -> Annotation says List<String>
        JavaType baseType = typeFactory.constructArrayType(String[].class, String.class);
        when(introspector.findSerializationContentType(any(Annotated.class), any(JavaType.class))).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertTrue(result.getContentType().hasStaticTyping());
    }

    @Test
    public void testRefineSerializationType_ContentTypeRefinement_Specialization() throws JsonMappingException {
        // List<String> -> Annotation says List<Object>
        // currRaw = String.class, keyClass = Object.class
        // String.class.isAssignableFrom(Object.class) is false.
        // Object.class.isAssignableFrom(String.class) is true.
        JavaType baseType = typeFactory.constructArrayType(String[].class, String.class);
        when(introspector.findSerializationContentType(any(Annotated.class), any(JavaType.class))).thenReturn(Object.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(Object.class, result.getContentType().getRawClass());
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineSerializationType_ContentTypeRefinement_Incompatible() throws JsonMappingException {
        JavaType baseType = typeFactory.constructArrayType(Integer[].class, Integer.class);
        when(introspector.findSerializationContentType(any(Annotated.class), any(JavaType.class))).thenReturn(String.class);

        introspector.refineSerializationType(config, annotated, baseType);
    }
}
